import hashlib

def hash_certificate(cert: str) -> str:
    if not cert:
        raise ValueError("Certificate content cannot be empty")
    hash_object = hashlib.sha256(cert.encode('utf-8'))
    return hash_object.hexdigest()

# Example usage
cert_example = "example_certificate_data"
hashed_cert = hash_certificate(cert_example)
print(f"Hashed Certificate: {hashed_cert}")
